    (document.fonts?.ready ?? Promise.resolve())
      .then(() => infographic.render(syntax))
      .catch((e) => console.error('Font readiness error', e));

    // Expose export for automated capture if needed.
    window.__exportSvgDataUrl = async () => {
      return await infographic.toDataURL({ type: 'svg' });
    };
  </script>
